package com.genealogy.review.repository;
import com.baomidou.mybatisplus.core.toolkit.Wrappers; import com.genealogy.review.entity.ReviewTaskEntity; import com.genealogy.review.repository.mybatis.ReviewTaskPersistenceMapper; import org.springframework.data.domain.*; import org.springframework.stereotype.Repository; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime; import java.util.*;
@Repository @Transactional(readOnly=true) public class ReviewTaskRepository { private final ReviewTaskPersistenceMapper mapper; public ReviewTaskRepository(ReviewTaskPersistenceMapper mapper){this.mapper=mapper;} @Transactional public ReviewTaskEntity save(ReviewTaskEntity e){if(e.getId()==null)mapper.insert(e);else if(mapper.updateAllById(e)!=1)throw new IllegalStateException("Review task update expected one row for id "+e.getId());return e;} @Transactional public ReviewTaskEntity saveAndFlush(ReviewTaskEntity e){return save(e);} public Optional<ReviewTaskEntity> findById(Long id){return Optional.ofNullable(id==null?null:mapper.selectById(id));} public List<ReviewTaskEntity> findAllById(Iterable<Long> ids){List<Long>v=new ArrayList<>();if(ids!=null)ids.forEach(v::add);return v.isEmpty()?List.of():mapper.selectBatchIds(v);} public Optional<ReviewTaskEntity> findFirstByRevisionIdOrderByReviewLevelAsc(Long revisionId){return Optional.ofNullable(mapper.selectOne(Wrappers.<ReviewTaskEntity>lambdaQuery().eq(ReviewTaskEntity::getRevisionId,revisionId).orderByAsc(ReviewTaskEntity::getReviewLevel).orderByAsc(ReviewTaskEntity::getId).last("limit 1")));} public List<ReviewTaskEntity> findByTraceIdOrderByCreatedAtAscIdAsc(UUID traceId){return mapper.selectList(Wrappers.<ReviewTaskEntity>lambdaQuery().eq(ReviewTaskEntity::getTraceId,traceId).orderByAsc(ReviewTaskEntity::getCreatedAt).orderByAsc(ReviewTaskEntity::getId));} public long countByClanIdAndStatusIn(Long clanId,Collection<String> statuses){if(statuses==null||statuses.isEmpty())return 0;return mapper.selectCount(Wrappers.<ReviewTaskEntity>lambdaQuery().eq(ReviewTaskEntity::getClanId,clanId).in(ReviewTaskEntity::getStatus,statuses));} public long countByClanIdAndStatusInAndCreatedAtBefore(Long clanId,Collection<String> statuses,LocalDateTime before){if(statuses==null||statuses.isEmpty())return 0;return mapper.selectCount(Wrappers.<ReviewTaskEntity>lambdaQuery().eq(ReviewTaskEntity::getClanId,clanId).in(ReviewTaskEntity::getStatus,statuses).lt(ReviewTaskEntity::getCreatedAt,before));} public List<ReviewTaskEntity> findRecentDashboardTasks(Long clanId,Pageable p){return mapper.selectList(Wrappers.<ReviewTaskEntity>lambdaQuery().eq(ReviewTaskEntity::getClanId,clanId).orderByDesc(ReviewTaskEntity::getCreatedAt).orderByDesc(ReviewTaskEntity::getId).last("limit "+p.getPageSize()+" offset "+p.getOffset()));} public List<ReviewTaskEntity> findTreeReviewTasksByRevisionIds(Long clanId,Collection<Long> revisionIds){if(revisionIds==null||revisionIds.isEmpty())return List.of();return mapper.selectList(Wrappers.<ReviewTaskEntity>lambdaQuery().eq(ReviewTaskEntity::getClanId,clanId).in(ReviewTaskEntity::getRevisionId,revisionIds).orderByAsc(ReviewTaskEntity::getRevisionId).orderByAsc(ReviewTaskEntity::getReviewLevel).orderByAsc(ReviewTaskEntity::getId));} public Page<ReviewTaskEntity> findByClanIdAndRevisionIdInOrderByCreatedAtDesc(Long clanId,Collection<Long> ids,Pageable p){return page(clanId,ids,null,p);} public Page<ReviewTaskEntity> findByClanIdAndRevisionIdInAndBranchIdInOrderByCreatedAtDesc(Long clanId,Collection<Long> ids,Collection<Long> branches,Pageable p){return page(clanId,ids,branches,p);} private Page<ReviewTaskEntity> page(Long clanId,Collection<Long> ids,Collection<Long> branches,Pageable p){if(ids==null||ids.isEmpty()||(branches!=null&&branches.isEmpty()))return new PageImpl<>(List.of(),p,0);var q=Wrappers.<ReviewTaskEntity>lambdaQuery().eq(ReviewTaskEntity::getClanId,clanId).in(ReviewTaskEntity::getRevisionId,ids);if(branches!=null)q.in(ReviewTaskEntity::getBranchId,branches);long total=mapper.selectCount(q);if(total==0)return new PageImpl<>(List.of(),p,0);q.orderByDesc(ReviewTaskEntity::getCreatedAt).orderByDesc(ReviewTaskEntity::getId).last("limit "+p.getPageSize()+" offset "+p.getOffset());return new PageImpl<>(mapper.selectList(q),p,total);} }
